#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>

// Compile without fast-math or contraction: every intermediate matches the
// original NumPy expression order, including division by tau.
extern "C" int field_lbm_collision(
    std::int64_t cells, double tau, double pref,
    const double* f, const double* rho, const double* cu,
    const double* usq, const double* ea, const double* ua,
    const double* weights, double* out) {
    if (cells < 0 || static_cast<std::uint64_t>(cells) >
            std::numeric_limits<std::size_t>::max() / (19 * sizeof(double)) ||
            !std::isfinite(tau) || tau == 0.0 || !std::isfinite(pref)) return 1;
    if (cells == 0) return 0;
    if (!f || !rho || !cu || !usq || !ea || !ua || !weights || !out) return 2;
    double pw[19];
    for (int q = 0; q < 19; ++q) pw[q] = pref * weights[q];
    for (std::int64_t cell = 0; cell < cells; ++cell) {
        for (int q = 0; q < 19; ++q) {
            const auto i = static_cast<std::size_t>(cell) * 19 + q;
            const double c = cu[i];
            const double equilibrium = (weights[q] * rho[cell]) *
                (((1.0 + 3.0 * c) + 4.5 * (c * c)) - 1.5 * usq[cell]);
            const double forcing = (pw[q] * rho[cell]) *
                (3.0 * (ea[i] - ua[cell]) + (9.0 * c) * ea[i]);
            out[i] = (f[i] - ((f[i] - equilibrium) / tau)) + forcing;
        }
    }
    return 0;
}

#include "moments.hpp"

#include "stream.hpp"

#pragma once
#include <cstdint>
#include <cstring>
#include <limits>

extern "C" int field_lbm_stream(std::int64_t cells, const double* fstar,
        const std::uint8_t* solid, const std::intptr_t* indices,
        const std::intptr_t* opposite, double* output) {
    if (cells<0 || cells>std::numeric_limits<std::int64_t>::max()/(19*sizeof(double)) ||
        static_cast<std::uint64_t>(cells)>std::numeric_limits<std::uintptr_t>::max()/(19*sizeof(double))) return 1;
    if (cells==0) return 0;
    if (!fstar || !solid || !indices || !opposite || !output) return 1;
    const auto count=cells*19;
    const auto bytes=static_cast<std::uintptr_t>(count)*sizeof(double);
    const auto source=reinterpret_cast<std::uintptr_t>(fstar);
    const auto destination=reinterpret_cast<std::uintptr_t>(output);
    const auto max_address=std::numeric_limits<std::uintptr_t>::max();
    if (source>max_address-bytes || destination>max_address-bytes ||
        (source<destination+bytes && destination<source+bytes)) return 1;
    for (int q=0;q<19;++q) if (opposite[q]<0 || opposite[q]>=19) return 1;
    // Validate every index, including solid cells, before writing any output.
    for (std::int64_t i=0;i<count;++i) if (indices[i]<0 || indices[i]>=count) return 1;
    for (std::int64_t i=0;i<cells;++i) {
        for (int q=0;q<19;++q) {
            const auto from=solid[i] ? 19*i+opposite[q] : indices[19*i+q];
            std::memcpy(output+19*i+q,fstar+from,sizeof(double));
        }
    }
    return 0;
}

