#include <array>
#include <cassert>
#include <limits>
#include "../src/field_engine/lbm_collision_native_v1/stream.hpp"
int main() {
    std::array<double,38> f;for (int i=0;i<38;++i) f[i]=i;
    std::uint8_t solid[2]={0,1};
    std::intptr_t indices[38],opposite[19];
    for (int i=0;i<38;++i) indices[i]=(i+5)%38;
    for (int q=0;q<19;++q) opposite[q]=18-q;
    struct Guard {double before;std::array<double,38> values;double after;};
    Guard output{719,{},971};auto out=output.values.data();
    assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)==0);
    for (int q=0;q<19;++q) assert(out[q]==q+5 && out[19+q]==37-q);
    solid[0]=1;
    assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)==0);
    for (int q=0;q<19;++q) assert(out[q]==18-q && out[19+q]==37-q);
    auto before=output.values;
    assert(field_lbm_stream(0,nullptr,nullptr,nullptr,nullptr,nullptr)==0);
    assert(field_lbm_stream(-1,f.data(),solid,indices,opposite,out)!=0);
    assert(field_lbm_stream(std::numeric_limits<std::int64_t>::max(),f.data(),solid,indices,opposite,out)!=0);
    assert(field_lbm_stream(2,nullptr,solid,indices,opposite,out)!=0);
    assert(field_lbm_stream(2,f.data(),nullptr,indices,opposite,out)!=0);
    assert(field_lbm_stream(2,f.data(),solid,nullptr,opposite,out)!=0);
    assert(field_lbm_stream(2,f.data(),solid,indices,nullptr,out)!=0);
    assert(field_lbm_stream(2,f.data(),solid,indices,opposite,nullptr)!=0);
    indices[37]=-1;assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)!=0);
    indices[37]=38;assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)!=0);indices[37]=4;
    opposite[0]=-1;assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)!=0);
    opposite[0]=19;assert(field_lbm_stream(2,f.data(),solid,indices,opposite,out)!=0);opposite[0]=18;
    assert(field_lbm_stream(2,f.data(),solid,indices,opposite,f.data())!=0);
    assert(field_lbm_stream(2,f.data(),solid,indices,opposite,f.data()+1)!=0);
    assert(output.before==719 && output.after==971 && output.values==before);
    for (int i=0;i<38;++i) assert(f[i]==i);
    return 0;
}
